import{_ as i,a0 as a,w as r,s as l,ao as A,I as s,a1 as e,A as n,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"如何通過簡單的3步恢復Windows 7同時刪除Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"如何通過簡單的3步恢復Windows 7同時刪除Ubuntu | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何通過簡單的3步恢復Windows 7同時刪除Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何通過簡單的3步恢復Windows 7同時刪除Ubuntu | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150122 How To Recover Windows 7 And Delete Ubuntu In 3 Easy Steps","title":"如何通過簡單的3步恢復Windows 7同時刪除Ubuntu","tag":"201503","desc":""},"relativePath":"201503/20150122 How To Recover Windows 7 And Delete Ubuntu In 3 Easy Steps.md","filePath":"[post].md"}'),d={name:"201503/20150122 How To Recover Windows 7 And Delete Ubuntu In 3 Easy Steps.md"};function u(m,p,b,g,w,h){const o=a("Link");return r(),l("div",null,[p[15]||(p[15]=A('<h1 id="如何通過簡單的3步恢復windows-7同時刪除ubuntu" tabindex="-1">如何通過簡單的3步恢復Windows 7同時刪除Ubuntu <a class="header-anchor" href="#如何通過簡單的3步恢復windows-7同時刪除ubuntu" aria-label="Permalink to “如何通過簡單的3步恢復Windows 7同時刪除Ubuntu”">​</a></h1><h3 id="説明" tabindex="-1">説明 <a class="header-anchor" href="#説明" aria-label="Permalink to “説明”">​</a></h3><p>寫這篇文章對我來説是一件奇怪的事情，因為我通常都是提倡安裝Ubuntu而卸載Windows的。</p><p>讓今天寫這篇文章更加奇怪的是，我決定在微軟決定終止對Windows7的主流支持的這一天來寫。</p><p>那麼為什麼我現在要寫這篇文章呢？</p><p>到目前為止我曾經在很多場合被問到如何從一個裝有Windows7或Windows8的雙系統中刪除Ubuntu系統，因此寫這篇文章就變得有意義了。</p><p>我在聖誕節期間瀏覽了人們在我文章中的留言，感覺是時候把缺失的文章寫完同時更新一下那些比較老的又需要關注的文章了。</p><p>我打算把一月份剩下的時間都用在這上面。這是第一步。如果你的電腦上安裝了Windows7和Ubuntu雙系統，同時你不想通過恢復出廠設置的方式恢復Windows7系統，那麼請參考該教程。(注意：對於Windows8系統，有一個獨立的教程)</p><h3 id="刪除ubuntu系統需要的步驟" tabindex="-1">刪除Ubuntu系統需要的步驟 <a class="header-anchor" href="#刪除ubuntu系統需要的步驟" aria-label="Permalink to “刪除Ubuntu系統需要的步驟”">​</a></h3><ol><li>通過修復Windows啓動項來刪除Grub</li><li>刪除Ubuntu系統所在分區</li><li>擴展Windows系統分區</li></ol><h3 id="備份系統" tabindex="-1">備份系統 <a class="header-anchor" href="#備份系統" aria-label="Permalink to “備份系統”">​</a></h3><p>在你開始之前，我建議為你的系統保留一個備份。</p><p>我建議你不要放棄備份的機會，但也不要使用微軟自帶的工具。</p>',13)),s("p",null,[e(o,{href:"http://linux.about.com/od/LinuxNewbieDesktopGuide/ss/Create-A-Recovery-Drive-For-All-Versions-Of-Windows.htm"},{default:n(()=>[...p[0]||(p[0]=[t("點擊查看如何使用Macrinum Reflect備份你的驅動",-1)])]),_:1})]),p[16]||(p[16]=A('<p>如果Ubuntu中有你希望保存的數據，現在就登錄進去然後將數據保存到外部硬盤驅動器，USB驅動器或者DVD中。</p><h3 id="步驟1-刪除grub啓動菜單" tabindex="-1">步驟1 - 刪除Grub啓動菜單 <a class="header-anchor" href="#步驟1-刪除grub啓動菜單" aria-label="Permalink to “步驟1 - 刪除Grub啓動菜單”">​</a></h3><p><img src="http://1.bp.blogspot.com/-arVqwMLpJRQ/VLWbHWkqYsI/AAAAAAAAHmw/kn3jDPOltX4/s1600/grubmenu.jpg" alt=""></p><p>當你啓動系統的時候你會看見一個與上圖類似的菜單。</p><p>要想刪除這個菜單直接進入Windows系統，你必須修復主引導記錄。</p><p>要達到這個目的，我將向你展示如何創建一個系統恢復盤，如何從恢復盤中啓動以及如何修復主引導記錄。</p><p><img src="http://2.bp.blogspot.com/-ML2JnNc8OWY/VLWcAovwGNI/AAAAAAAAHm4/KH778_MkU7U/s1600/recoverywindow1.PNG" alt=""></p><p>按下“開始”按鈕，搜索“備份和還原”。點擊出現的圖標。</p><p>將會打開一個與上圖一樣的窗口。</p><p>點擊“創建系統修復光盤”。</p>',10)),s("p",null,[p[2]||(p[2]=t("你需要一個",-1)),e(o,{href:"http://www.amazon.co.uk/gp/product/B0006L2HTK/ref=as_li_qf_sp_asin_il_tl?ie=UTF8&camp=1634&creative=6738&creativeASIN=B0006L2HTK&linkCode=as2&tag=evelinuse-21&linkId=3R363EA63XB4Z3IL"},{default:n(()=>[...p[1]||(p[1]=[t("空的DVD盤",-1)])]),_:1}),p[3]||(p[3]=t("。",-1))]),p[17]||(p[17]=A(`<p><img src="http://2.bp.blogspot.com/-r0GUDZ4AAMI/VLWfJ0nuJLI/AAAAAAAAHnE/RloNqdXLLcY/s1600/recoverywindow2.PNG" alt=""></p><p>將空的DVD盤插入到驅動器中然後從下拉列表中選擇你的DVD驅動器。</p><p>點擊“創建光盤”。</p><p>將光盤留在電腦中並重啓電腦，當出現從CD中啓動的消息的時候按下鍵盤上的“回車”鍵。</p><p><img src="http://2.bp.blogspot.com/-VPSD50bmk2E/VLWftBg7HxI/AAAAAAAAHnM/APVzvPg4rC0/s1600/recoveryoptionschooselanguage.jpg" alt=""></p><p>屏幕上會出現“系統恢復選項”。</p><p>它會要求你選擇你的鍵盤佈局方式。</p><p>從列表中選擇合適的選項，然後點擊“下一步”。</p><p><img src="http://2.bp.blogspot.com/-klK4SihPv0E/VLWgLiPO1mI/AAAAAAAAHnU/DUgxH6N2SFE/s1600/RecoveryOptions.jpg" alt=""></p><p>下一個界面讓你選擇你想修復的操作系統。</p><p>或者你可以使用早先保存的系統鏡像恢復系統。</p><p>選中上面的選項然後點擊“下一步”。</p><p><img src="http://2.bp.blogspot.com/-WOk-Unm6cCQ/VLWgvzoBgzI/AAAAAAAAHng/vfxm1jhW1Ms/s1600/RecoveryOptions2.jpg" alt=""></p><p>現在你將會看到一個有修復硬盤和恢復您的系統等選項的界面。</p><p>你需要做的是修復主引導記錄，而這可以通過領命提示符來完成。</p><p>點擊“命令提示符”。</p><p><img src="http://4.bp.blogspot.com/-duT-EUC0yuo/VLWhHygCApI/AAAAAAAAHno/bO7UlouyR9M/s1600/FixMBR.jpg" alt=""></p><p>現在只需要把下面的命令輸入到命令提示符中：</p><pre><code>bootrec.exe /fixmbr
</code></pre><p>接下來將會出現一條消息，提示操作已經成功完成。</p><p>你現在就可以關閉命令提示符窗口了。</p><p>點擊“重啓”按鈕然後取出DVD。</p><p>你的電腦就會直接啓動進入Windows7系統了。</p><h3 id="步驟-2-刪除ubuntu分區" tabindex="-1">步驟 2 - 刪除Ubuntu分區 <a class="header-anchor" href="#步驟-2-刪除ubuntu分區" aria-label="Permalink to “步驟 2 - 刪除Ubuntu分區”">​</a></h3><p><img src="http://4.bp.blogspot.com/-1OM0b3qBeHk/VLWh89gtgVI/AAAAAAAAHn0/ECHIARNCRp8/s1600/diskmanagement1.PNG" alt=""></p><p>要刪除Ubuntu你需要使用Windows系統提供的“磁盤管理”工具。</p><p>按下“開始”按鈕然後在搜索框中輸入“創建和格式化磁盤分區”。將會出現一個與上圖類似的窗口。</p><p>現在上面我的屏幕將不再和你的一模一樣了，不過也不會相差太多。你會看到第0塊磁盤有101MB的未分配空間，另外還有4個分區。</p><p>這101MB的空間是之前我安裝Windows7時犯的一個錯誤。驅動器C是Windows7系統，下一個分區(46.57GB)是Ubuntu的根分區。287G的分區是/HOME分區，8G的分區是交換空間。</p><p>對於Windows系統來説，我們真正需要的只有驅動器C，所以剩下的是可以刪掉的。</p><p><strong>注意: 注意一下.你的磁盤上可能有恢復分區。 不要刪除恢復分區。它們應該有專門的卷標，文件系統也許是NTFS或FAT32</strong></p><p><img src="http://3.bp.blogspot.com/-8YUE2p5Fj8Q/VLWlHXst6JI/AAAAAAAAHoQ/BJC57d9Nilg/s1600/deletevolume.png" alt=""></p><p>在你希望刪除的分區上單擊右鍵(例如：root,home和swap分區),然後從彈出的菜單中點擊“刪除卷”。</p><p><strong>(不要刪除任何NTFS或者FAT32文件系統的分區！)</strong></p><p>對於剩下的兩個分區重複執行上面的操作。</p><p><img src="http://3.bp.blogspot.com/-IGbJLkc_soY/VLWk1Vh0XAI/AAAAAAAAHoA/v7TVFT0rC0E/s1600/diskmanagement2.PNG" alt=""></p><p>分區被刪除後你將會有很大的一片空閒區域。右鍵點擊空閒區域然後選擇刪除。</p><p><img src="http://4.bp.blogspot.com/-2xUBkWHpnC4/VLWk9cYXGZI/AAAAAAAAHoI/8F2ANkorGeM/s1600/diskmanagement3.PNG" alt=""></p><p>現在你的磁盤將包含驅動器C和一大片沒有分配的空間。</p><h3 id="步驟-3-擴展windows分區" tabindex="-1">步驟 3 - 擴展Windows分區 <a class="header-anchor" href="#步驟-3-擴展windows分區" aria-label="Permalink to “步驟 3 - 擴展Windows分區”">​</a></h3><p><img src="http://4.bp.blogspot.com/-pLV5L3CvQ1Y/VLWmh-5SKTI/AAAAAAAAHoc/7sJzITyvduo/s1600/diskmanagement4.png" alt=""></p><p>最後一步是擴展Windows以便於將它再變成一個大的分區。</p><p>右鍵點擊Windows分區(C盤)，然後選擇“擴展卷”。</p><p><img src="http://1.bp.blogspot.com/-vgmw_N2WZWw/VLWm7i5oSxI/AAAAAAAAHok/k0q_gnIik9A/s1600/extendvolume1.PNG" alt=""></p><p>當出現左面的窗口的時候點擊“下一步”。</p><p><img src="http://3.bp.blogspot.com/-WLA86V-Au8g/VLWnTq5RpAI/AAAAAAAAHos/6vzjLNkrwRQ/s1600/extendvolume2.PNG" alt=""></p><p>接下來是一個嚮導界面，在這裏你可以選擇擴展到那個盤，同時修改擴展的大小。</p><p>默認情況下，嚮導界面將顯示它能從未分配區域中獲取的最大的磁盤空間數。</p><p>接受默認的選項，然後點擊“下一步”。</p><p><img src="http://4.bp.blogspot.com/-1rhTJvwem0k/VLWnvx7fWFI/AAAAAAAAHo0/D-4HA8E8y2c/s1600/extendvolume3.PNG" alt=""></p><p>最後的界面展示了你在前一個界面中的選擇結果。</p><p>點擊“結束”進行磁盤擴展。</p><p><img src="http://2.bp.blogspot.com/-CpuLXSYyPKY/VLWoEGU3sCI/AAAAAAAAHo8/7o5G4W4b7zU/s1600/diskmanagement5.PNG" alt=""></p><p>從上圖中你可以看到，我的Windows分區佔據了整個磁盤(除了我之前安裝Windows的時候偶然創建的101MB的空間)。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p><img src="http://1.bp.blogspot.com/-h1Flo2aGFcI/VLWogr2zfMI/AAAAAAAAHpE/2ypTSgR8_iM/s1600/fullwindowsscreen.PNG" alt=""></p><p>這就是全部內容。一個致力於Linux的網站剛剛向你展示瞭如何移除Linux然後用Windows7取而代之。</p><p>有任何疑問可以在下面評論區留言。</p><hr>`,59)),s("p",null,[p[5]||(p[5]=t("via: ",-1)),e(o,{href:"http://www.everydaylinuxuser.com/2015/01/how-to-recover-windows-7-and-delete.html"},{default:n(()=>[...p[4]||(p[4]=[t("http://www.everydaylinuxuser.com/2015/01/how-to-recover-windows-7-and-delete.html",-1)])]),_:1})]),s("p",null,[p[8]||(p[8]=t("作者：Gary Newell 譯者：",-1)),e(o,{href:"https://github.com/Medusar"},{default:n(()=>[...p[6]||(p[6]=[t("Medusar",-1)])]),_:1}),p[9]||(p[9]=t(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...p[7]||(p[7]=[t("wxy",-1)])]),_:1})]),s("p",null,[p[12]||(p[12]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...p[10]||(p[10]=[t("LCTT",-1)])]),_:1}),p[13]||(p[13]=t(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:n(()=>[...p[11]||(p[11]=[t("Linux中國",-1)])]),_:1}),p[14]||(p[14]=t(" 榮譽推出",-1))])])}const L=i(d,[["render",u]]);export{c as __pageData,L as default};
